'use client'

import { useSidebar } from '@repo/ui/components/sidebar'
import { useEffect, useState } from 'react'

const VIEW_BOX = '55 25 405 460'

type Leaf = {
  left: string
  size: number
  opacity: number
  rotate: number
  /** Доля круга, пройденная к первому кадру: 0 — над полосой, 1 — под ней. */
  phase: number
  /** Секунд на полный круг. */
  duration: number
}

/**
 * Осенняя листва — фоновый слой строки школы в сайдбаре (сентябрь).
 *
 * Живёт отдельным файлом не ради переиспользования, а ради веса: обвод листа —
 * 7.5 КБ данных, и в компоненте навигации они забивали всё остальное. Пропсов
 * нет намеренно: потребитель один, а плотность и палитра здесь не «настройка»,
 * а часть рисунка — понадобится второй вариант, тогда и появится параметр.
 *
 * Слой рассчитан на родителя с `relative isolate overflow-hidden`: `-z-10`
 * кладёт листья поверх фона кнопки, но под её текст, а обрезает их скругление
 * самой кнопки.
 *
 * Общий сдвиг фазы разыгрывается заново на каждое раскрытие сайдбара. Свёрнутый
 * сайдбар прячет слой через `display: none`, а на таком элементе анимация не
 * идёт и при возврате стартует с нуля — без сдвига каждое открытие показывало
 * бы один и тот же кадр. Сдвиг общий на всех, а не свой у каждого листа: фазы
 * уже разложены по кругу равномерно, и одинаковый поворот эту равномерность
 * сохраняет, а восемнадцать независимых бросков сбивали бы листья в кучу.
 *
 * До первого эффекта слой не рисуется вовсе — так `Math.random()` не попадает в
 * серверную разметку и гидратации не с чем расходиться.
 */
export function AutumnLeaves() {
  const { state } = useSidebar()
  const [shift, setShift] = useState<number | null>(null)

  useEffect(() => {
    if (state === 'expanded') setShift(Math.random())
  }, [state])

  if (shift === null) return null

  return (
    <span
      aria-hidden
      className="pointer-events-none absolute inset-0 -z-10 text-orange-500 group-data-[collapsible=icon]:hidden"
    >
      <MapleLeafDefs />
      {LEAVES.map((leaf, i) => (
        <svg
          key={i}
          viewBox={VIEW_BOX}
          className="animate-leaf-fall absolute top-0"
          style={{
            left: leaf.left,
            width: leaf.size,
            height: leaf.size,
            opacity: leaf.opacity,
            transform: `rotate(${leaf.rotate}deg)`,
            animationDuration: `${leaf.duration}s`,
            animationDelay: `-${(leaf.duration * ((leaf.phase + shift) % 1)).toFixed(1)}s`,
          }}
        >
          <use href="#maple-leaf" />
        </svg>
      ))}
    </span>
  )
}

